133	func newRepoMirrorCreateCmd() *cobra.Command {
134		var (
135			noWait      bool
136			waitTimeout time.Duration
137		)
138		cmd := &cobra.Command{
139			Use:   "create [github-url] [cluster-host]",
140			Short: "Register a GitHub mirror on a cluster",
141			Long: "With no arguments, launches an interactive wizard: pick repos to " +
142				"mirror, pick one or more regions, then creates every (repo, region) " +
143				"mirror in parallel and prints the clone URLs.\n\n" +
144				"With a <github-url>, registers a mirror placement for that repo on " +
145				"the target cluster, then waits for the initial GitHub→EntireDB clone " +
146				"to finish so `git clone` works on return. Pass --no-wait to return " +
147				"as soon as the placement is registered. Idempotent on " +
148				"(upstream, cluster). The cluster-host defaults to " +
149				defaultClusterHost + " when omitted (the interactive wizard, with " +
150				"no args, instead lets you pick clusters).",
151			Example: "  entire repo mirror create\n" +
152				"  entire repo mirror create github.com/octocat/hello-world\n" +
153				"  entire repo mirror create github.com/octocat/hello-world aws-us-east-2.entire.io",
154			Args: cobra.RangeArgs(0, 2),
155			RunE: func(cmd *cobra.Command, args []string) error {
156				if len(args) == 0 {
157					return runMirrorCreateWizard(cmd, noWait, waitTimeout)
158				}
159				owner, repo, err := parseGitHubURL(args[0])
160				if err != nil {
161					cmd.SilenceUsage = true
162					return fmt.Errorf("invalid <github-url>: %w", err)
163				}
164				// The non-interactive one-shot keeps a fixed default cluster
165				// (defaultClusterHost) when [cluster-host] is omitted — catalog-based
166				// cluster guessing is intentionally limited to the interactive
167				// wizard (the no-args path above), so scripts get stable behavior.
168				clusterHost := clusterArg(args)
169				if err := validateClusterHost(clusterHost); err != nil {
170					cmd.SilenceUsage = true
171					return fmt.Errorf("invalid [cluster-host]: %w", err)
172				}
173				return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
174					errW := cmd.ErrOrStderr()
175					stop := startSpinner(errW, fmt.Sprintf("Cloning %s/%s into %s", owner, repo, clusterHost))
176					// nil onStatus: the one-shot's single spinner shows liveness; the
177					// per-mirror progress lines are the wizard's concern.
178					outcome, err := createAndAwaitMirror(ctx, c, owner, repo, clusterHost, noWait, waitTimeout, nil)
179					// Only a confirmed-ready clone earns the ✓; everything else
180					// (empty, --no-wait, suspended, failed, timeout) erases the line
181					// and lets reportOneShotMirror print the specific outcome.
182					stop(err == nil && outcome.polled && outcome.status == coreapi.MirrorStatusReady)
183					return reportOneShotMirror(cmd.OutOrStdout(), errW, outcome, err)
184				})
185			},
186		}
187		cmd.Flags().BoolVar(&noWait, "no-wait", false, "return once the placement is registered, without waiting for the initial clone")
188		cmd.Flags().DurationVar(&waitTimeout, "wait-timeout", 30*time.Minute, "how long to wait for the initial clone to finish")
189		return cmd
190	}
