290	func newRepoMirrorListCmd() *cobra.Command {
291		var cluster, provider, owner string
292		var showAvailable bool
293		cmd := &cobra.Command{
294			Use:   "list",
295			Short: "List mirrors you can see (or, with --show-available, repos you could mirror)",
296			Args:  cobra.NoArgs,
297			RunE: func(cmd *cobra.Command, _ []string) error {
298				if showAvailable {
299					return runCoreList(cmd, availableMirrorColumns, availableMirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.AvailableMirror, error) {
300						// Computed live from GitHub using your own login, so name the
301						// core being dialled (same rationale as the existing-mirror
302						// banner). --cluster/--provider don't apply here: the
303						// onboardable set is cluster-agnostic and GitHub-only.
304						if !jsonRequested(cmd) {
305							fmt.Fprintf(cmd.ErrOrStderr(), "Listing repos you could mirror, via %s\n", c.CoreOrigin())
306						}
307						var params coreapi.ListAvailableMirrorsParams
308						if owner != "" {
309							params.Owner = coreapi.NewOptString(owner)
310						}
311						out, err := c.ListAvailableMirrors(ctx, params)
312						if err != nil {
313							return nil, err
314						}
315						return out.Available, nil
316					})
317				}
318				return runCoreList(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.Mirror, error) {
319					// mirror list is identity-scoped: it shows the mirrors visible
320					// from the active login's federation, so naming that login server
321					// makes a surprising empty result legible — e.g. mirrors in a
322					// different deployment than the active context (--cluster is a
323					// filter, not a router). Name the core the client actually dials
324					// (c.CoreOrigin) so the banner can never diverge from where the
325					// request goes — in particular it reflects ENTIRE_TOKEN's aud,
326					// which a separately-resolved ResolveControlPlaneTarget would miss.
327					// On stderr so it never lands in a piped table; skipped for --json
328					// to keep machine output clean.
329					if !jsonRequested(cmd) {
330						fmt.Fprintf(cmd.ErrOrStderr(), "Listing mirrors on %s\n", c.CoreOrigin())
331					}
332					return fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Mirror, string, error) {
333						params := coreapi.ListMirrorsParams{}
334						if cluster != "" {
335							params.Cluster = coreapi.NewOptString(cluster)
336						}
337						if provider != "" {
338							params.Provider = coreapi.NewOptString(provider)
339						}
340						if owner != "" {
341							params.Owner = coreapi.NewOptString(owner)
342						}
343						if cursor != "" {
344							params.PageToken = coreapi.NewOptString(cursor)
345						}
346						out, err := c.ListMirrors(ctx, params)
347						if err != nil {
348							return nil, "", err
349						}
350						return out.Mirrors, out.NextPageToken.Or(""), nil
351					})
352				})
353			},
354		}
355		cmd.Flags().StringVar(&cluster, "cluster", "", "filter by cluster public host")
356		cmd.Flags().StringVar(&provider, "provider", "", "filter by upstream provider (e.g. github)")
357		cmd.Flags().StringVar(&owner, "owner", "", "filter by upstream owner login")
358		cmd.Flags().BoolVar(&showAvailable, "show-available", false, "instead of existing mirrors, list GitHub repos you could onboard as mirrors (ignores --cluster/--provider)")
359		return cmd
360	}
