34	// repoColumns is the human table/field view of a repo, shared by list and
35	// get. CLUSTER/STATE come from optional fields, shown as "-" when unset.
36	var repoColumns = []string{"ID", "NAME", "PROJECT", "CLUSTER", "STATE"}
37	
38	func repoRow(r coreapi.Repo) []string {
39		state := ""
40		if v, ok := r.State.Get(); ok {
41			state = string(v)
42		}
43		return []string{r.ID, r.Name, r.OwningProjectId, r.ClusterHost.Or("-"), state}
44	}
45	
46	// repoRemoteURL synthesizes the entire:// clone/remote URL for a repo from
47	// its resolved cluster host and path — the form `git clone` and
48	// `git remote add` accept, which git-remote-entire reads back as the repo
49	// slug from the URL path. Returns "" when either coordinate is missing (a
50	// still-provisioning repo may not have them yet); a half-formed URL is worse
51	// than none.
52	func repoRemoteURL(r coreapi.Repo) string {
53		host := strings.TrimSpace(r.ClusterHost.Or(""))
54		path := strings.TrimSpace(r.Path.Or(""))
55		if host == "" || path == "" {
56			return ""
57		}
58		return "entire://" + host + "/" + strings.TrimPrefix(path, "/")
59	}
60	
61	// repoCreateOutput renders a created repo as JSON with a synthesized `remote`
62	// field merged in — the entire:// URL callers paste into `git clone` or
63	// `git remote add`. The repo carries a custom marshaler plus arbitrary
64	// additional properties, so it can't simply be embedded in a wrapper struct;
65	// instead it's round-tripped through its own encoder and the remote is merged
66	// into the resulting object. The synthesis only fills a gap: if the wire
67	// object already carries a `remote` (a future first-class field, or one
68	// arriving via additional properties) it's left untouched, so the
69	// server-provided value always wins. The field is omitted when the clone
70	// coordinates aren't resolvable yet rather than emitted half-formed.
71	func repoCreateOutput(r *coreapi.Repo) (any, error) {
72		if r == nil {
73			return nil, errors.New("nil repo")
74		}
75		raw, err := json.Marshal(r)
76		if err != nil {
77			return nil, fmt.Errorf("encode repo: %w", err)
78		}
79		var obj map[string]json.RawMessage
80		if err := json.Unmarshal(raw, &obj); err != nil {
81			return nil, fmt.Errorf("decode repo: %w", err)
82		}
83		if _, ok := obj["remote"]; !ok {
84			if remote := repoRemoteURL(*r); remote != "" {
85				encoded, err := json.Marshal(remote)
86				if err != nil {
87					return nil, fmt.Errorf("encode remote: %w", err)
88				}
89				obj["remote"] = encoded
90			}
91		}
92		return obj, nil
93	}
