95	func newRepoCreateCmd() *cobra.Command {
96		var (
97			projectID   string
98			clusterHost string
99		)
100		cmd := &cobra.Command{
101			Use:   "create <name>",
102			Short: "Create a repository in a project",
103			Args:  cobra.ExactArgs(1),
104			RunE: func(cmd *cobra.Command, args []string) error {
105				return runCoreJSON(cmd, func(ctx context.Context, c *coreapi.Client) (any, error) {
106					projID, err := resolveProjectRef(ctx, c, projectID)
107					if err != nil {
108						return nil, err
109					}
110					body := &coreapi.CreateRepoInputBody{
111						Name:      args[0],
112						ProjectId: projID,
113					}
114					if clusterHost != "" {
115						body.ClusterHost = coreapi.NewOptString(clusterHost)
116					}
117					created, err := c.CreateRepo(ctx, body)
